package com.crazy4lamb.crmbi.controller;
import static com.crazy4lamb.crmbi.controller.AuthController.user;import static com.crazy4lamb.crmbi.core.Api.ok;import com.crazy4lamb.crmbi.core.*;import com.crazy4lamb.crmbi.service.AclService;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/chart") public class ChartController{private final Db db;private final AclService acl;private final DashboardController dashboard;public ChartController(Db db,AclService acl,DashboardController dashboard){this.db=db;this.acl=acl;this.dashboard=dashboard;}
 @GetMapping("/meta")public Map<String,Object>meta(HttpServletRequest r){return db.tx(user(r),x->ok(Map.of("chartTypes",pairs("bar","柱状图","bar_h","横向柱状图","line","折线图","area","面积图","pie","饼图","doughnut","环图","scatter","散点图","heatmap","热力图","funnel","漏斗图","radar","雷达图","gauge","仪表盘"),"palettes",List.of(List.of("multi","多巴胺"),List.of("purple","科技紫")),"aggs",pairs("sum","求和","count","计数","avg","平均"),"sortStrategies",List.of(List.of("value_desc","按值降序"),List.of("axis","按维度顺序")),"scopes",List.of(List.of("global","全量数据"),List.of("dept","本部门数据"),List.of("self","仅本人数据")),"sumModes",List.of(List.of("latest","当日"),List.of("last30","近 30 天")),"reports",reports())));}
 @GetMapping("/list")public Map<String,Object>list(HttpServletRequest r){return db.tx(user(r),x->ok(db.many("select w.*,r.name report_name,m.name metric_name from bi_widget w left join rpt_report r on r.id=w.report_id left join bi_metric m on m.id=w.metric_id order by w.widget_type,w.id")));}
 @GetMapping("/{id}")public Map<String,Object>one(@PathVariable int id,HttpServletRequest r){return db.tx(user(r),x->{Map<String,Object>w=db.one("select * from bi_widget where id=:id",Map.of("id",id));if(w==null)throw ApiException.notFound("组件不存在");return ok(w);});}
 @GetMapping("/{id}/data")public Map<String,Object>data(@PathVariable int id,HttpServletRequest r){return db.tx(user(r),x->{Map<String,Object>w=db.one("select * from bi_widget where id=:id",Map.of("id",id));if(w==null)throw ApiException.notFound("组件不存在");return ok(dashboard.render(w).get("data"));});}
 @PostMapping("/preview")public Map<String,Object>preview(@RequestBody Map<String,Object>b,HttpServletRequest r){Map<String,Object>w=new LinkedHashMap<>();w.put("code","preview");w.put("name",b.getOrDefault("name","预览"));w.put("widget_type","chart");w.put("chart_type",b.getOrDefault("chartType","bar"));w.put("scope",b.getOrDefault("scope","global"));return db.tx(user(r),x->ok(dashboard.render(w).get("data")));}
 @GetMapping("/sample/{reportId}")public Map<String,Object>sample(@PathVariable int reportId,HttpServletRequest r){return ok(Map.of("columns",List.of(),"rows",List.of()));}
 @PostMapping public Map<String,Object>create(@RequestBody Map<String,Object>b,HttpServletRequest r){design(user(r));return db.tx(user(r),x->{String code=String.valueOf(b.getOrDefault("code","chart_"+Long.toString(System.currentTimeMillis(),36)));Number id=db.insertId("insert into bi_widget(code,name,widget_type,chart_type,report_id,dimension_keys,series,filters,sort_strategy,limit_rows,scope,style,unit,status) values(:code,:name,'chart',:chart,:report,cast(:dims as jsonb),cast(:series as jsonb),cast(:filters as jsonb),:sort,:limit,:scope,cast(:style as jsonb),:unit,'1')",widgetParams(b,code,null));db.update("insert into sys_acl(role_code,res_type,res_key) values(:role,'chart',:code) on conflict do nothing",Map.of("role",user(r).role(),"code",code));return ok(Map.of("id",id,"code",code),"统计图已创建");});}
 @PutMapping("/{id}")public Map<String,Object>update(@PathVariable int id,@RequestBody Map<String,Object>b,HttpServletRequest r){design(user(r));return db.tx(user(r),x->{Map<String,Object>old=db.one("select code from bi_widget where id=:id and widget_type='chart'",Map.of("id",id));if(old==null)throw ApiException.notFound("统计图不存在");db.update("update bi_widget set name=:name,chart_type=:chart,report_id=:report,dimension_keys=cast(:dims as jsonb),series=cast(:series as jsonb),filters=cast(:filters as jsonb),sort_strategy=:sort,limit_rows=:limit,scope=:scope,style=cast(:style as jsonb),unit=:unit,updated_at=now() where id=:id",widgetParams(b,String.valueOf(old.get("code")),id));return ok(null,"已保存");});}
 @DeleteMapping("/{id}")public Map<String,Object>delete(@PathVariable int id,HttpServletRequest r){design(user(r));return db.tx(user(r),x->{Map<String,Object>w=db.one("select code from bi_widget where id=:id and widget_type='chart'",Map.of("id",id));if(w==null)throw ApiException.notFound("统计图不存在");db.update("delete from bi_widget where id=:id",Map.of("id",id));db.update("delete from sys_acl where res_type='chart' and res_key=:code",Map.of("code",w.get("code")));return ok(null,"已删除");});}
 private List<Map<String,Object>>reports(){List<Map<String,Object>>rs=db.many("select r.id,r.code,r.name,r.category,d.name dataset_name from rpt_report r join rpt_dataset d on d.id=r.dataset_id order by r.category,r.id"),fs=db.many("select report_id,field_key,field_name,field_type,field_role,agg_fn,is_custom from rpt_report_field order by report_id,sort_no,id");rs.forEach(r->r.put("fields",fs.stream().filter(f->Objects.equals(r.get("id"),f.get("report_id"))).toList()));return rs;}
 private Map<String,Object>widgetParams(Map<String,Object>b,String code,Integer id){Map<String,Object>p=new LinkedHashMap<>();p.put("id",id);p.put("code",code);p.put("name",b.getOrDefault("name","未命名统计图"));p.put("chart",b.getOrDefault("chartType","bar"));p.put("report",b.get("reportId"));p.put("dims",json(b.getOrDefault("dims",List.of())));p.put("series",json(b.getOrDefault("series",List.of())));p.put("filters",json(b.getOrDefault("filters",List.of())));p.put("sort",b.getOrDefault("sortStrategy","value_desc"));p.put("limit",b.getOrDefault("limit",20));p.put("scope",b.getOrDefault("scope","global"));p.put("style",json(b.getOrDefault("style",Map.of())));p.put("unit",b.get("unit"));return p;}
 private static String json(Object value){try{return new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(value);}catch(Exception e){throw ApiException.bad("配置格式无效");}}
 private void design(UserPrincipal u){acl.require(u,"action","widget:design","无权限：需要「统计图设计」权限");}private static List<Map<String,Object>>pairs(String...v){List<Map<String,Object>>o=new ArrayList<>();for(int i=0;i<v.length;i+=2)o.add(Map.of("value",v[i],"label",v[i+1]));return o;}}
